-- --- checks -------------------------------------------------------------------------------------------------
ALTER TABLE report_schedules
  ADD CONSTRAINT ck_report_schedules__run_at_minute CHECK (run_at_minute BETWEEN 0 AND 1439),
  ADD CONSTRAINT ck_report_schedules__frequency CHECK (
    (frequency = 'daily' AND day_of_week IS NULL AND day_of_month IS NULL)
    OR (frequency = 'weekly' AND day_of_week BETWEEN 1 AND 7 AND day_of_month IS NULL)
    OR (frequency = 'monthly' AND day_of_month BETWEEN 1 AND 28 AND day_of_week IS NULL)
  ),
  ADD CONSTRAINT ck_report_schedules__recipients CHECK (cardinality(recipient_user_ids) BETWEEN 1 AND 50),
  ADD CONSTRAINT ck_report_schedules__filters CHECK (jsonb_typeof(filters) = 'object'),
  ADD CONSTRAINT ck_report_schedules__timezone CHECK (timezone = 'Asia/Bangkok'),
  ADD CONSTRAINT ck_report_schedules__next_run CHECK (NOT active OR next_run_at IS NOT NULL);

ALTER TABLE report_runs
  ADD CONSTRAINT ck_report_runs__filters CHECK (jsonb_typeof(filters) = 'object'),
  ADD CONSTRAINT ck_report_runs__succeeded CHECK (status <> 'succeeded' OR (file_object_id IS NOT NULL AND row_count IS NOT NULL AND finished_at IS NOT NULL)),
  ADD CONSTRAINT ck_report_runs__failed CHECK (status <> 'failed' OR (error IS NOT NULL AND finished_at IS NOT NULL)),
  ADD CONSTRAINT ck_report_runs__origin CHECK (schedule_id IS NOT NULL OR requested_by IS NOT NULL);
